rows.css:
.card {
    width: 825px;
    height: 1125px;
    border-radius: 25px;
    text-align: center;
    display: flex;
    flex-direction: column;
    background-color: hsl(220, 24%, 30%);
    //border: 45px solid hsl(220, 23%, 10%);
    color: hsl(220, 23%, 70%);
    font-weight: 600;
    font-size: 100px;
    background-image: url({{assets.card-back}});
    background-size: cover;
}
.card .content {
    flex: 1;
    padding: 50px;
    padding-top: 350px;
}

.card {
    width: 825px;
    height: 1125px;
    border-radius: 25px;
    text-align: center;
    display: flex;
    flex-direction: column;
    font-weight: 600;
    font-size: 40px;
    background-color: hsl({{card.hue}}, 30%, 50%);
}
.card .header {
    border-top-left-radius: 25px;
    border-top-right-radius: 25px;
    font-size: 60px;
    font-weight: 600;
    padding: 45px;
    padding-top: 55px;
    background-color: hsl({{card.hue}}, 30%, 50%);
    color: hsl({{card.hue}}, 30%, 20%);
    background: radial-gradient(
        hsl({{card.hue}}, 30%, 60%), 
        hsl({{card.hue}}, 30%, 50%));
}
.card .image {
    flex: 1;
    padding: 45px;
    font-size: 150px;
    background-image: url({{index assets card.name}});
    background-position: center;
    background-size: cover;
}
.card .footer {
    background-color: hsl({{card.hue}}, 30%, 30%);
    color: hsl({{card.hue}}, 30%, 80%);
    background: radial-gradient(
        hsl({{card.hue}}, 30%, 40%), 
        hsl({{card.hue}}, 30%, 30%));
    border-bottom-left-radius: 25px;
    border-bottom-right-radius: 25px;
}
.card .footer .description {
    height: 250px;
    padding: 60px;
    padding-top: 80px;
    {{#if (gt card.description.length 100)}}
        font-size: 36px;
    {{/if}}
}
.card .footer .id {
    text-align: right;
    padding-right: 60px;
    padding-bottom: 45px;
    color: hsl({{card.hue}}, 30%, 50%);
}
.overlay {
    width: 825px;
    height: 1125px;
    top: 0;
    position: absolute;
    background-image: url({{assets.card-overlay}});
    filter: hue-rotate({{add -50 card.hue}}deg);
    border-radius: 25px;
}

.card {
    width: 825px;
    height: 1125px;
    border-radius: 25px;
    text-align: center;
    display: flex;
    flex-direction: column;
    font-weight: 600;
    font-size: 32px;
    background-color: hsl({{card.hue}}, 0%, 50%);
    color: hsl({{card.hue}}, 0%, 20%);
    background: radial-gradient(
        hsl({{card.hue}}, 0%, 80%), 
        hsl({{card.hue}}, 0%, 60%));
}
.card .header {
    border-top-left-radius: 25px;
    border-top-right-radius: 25px;
    font-size: 70px;
    font-weight: 600;
    padding: 45px;
    padding-top: 55px;
}
.card .description {
    flex: 1;
    height: 250px;
    padding: 80px;
    padding-top: 0;
    text-align: left;
}
.card .footer {
    border-bottom-left-radius: 25px;
